<?php
use App\Http\Controllers\{ApprovalController,AuthController,BillingController,CustomerController,DashboardController,InvoiceController,ProductController,QuoteController,SettingsController};
use Illuminate\Support\Facades\Route;
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'login'])->name('login');Route::post('/login',[AuthController::class,'authenticate'])->middleware('throttle:6,1');Route::get('/register',[AuthController::class,'register'])->name('register');Route::post('/register',[AuthController::class,'store'])->middleware('throttle:4,1');});
Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::get('/approve/{token}',[ApprovalController::class,'show'])->middleware('throttle:60,1')->name('approval.show');
Route::post('/approve/{token}',[ApprovalController::class,'decide'])->middleware('throttle:10,1')->name('approval.decide');
Route::middleware('auth')->group(function(){Route::get('/billing',[BillingController::class,'index'])->name('billing');Route::middleware('subscribed')->group(function(){Route::get('/',DashboardController::class)->name('dashboard');Route::resource('customers',CustomerController::class)->except('show');Route::resource('products',ProductController::class)->except('show');Route::get('/quotes/create',[QuoteController::class,'create'])->name('quotes.create');Route::post('/quotes',[QuoteController::class,'store'])->name('quotes.store');Route::get('/quotes/{quote}',[QuoteController::class,'show'])->name('quotes.show');Route::post('/quotes/{quote}/revision',[QuoteController::class,'revision'])->name('quotes.revision');Route::get('/quotes/{quote}/edit',[QuoteController::class,'edit'])->name('quotes.edit');Route::put('/quotes/{quote}',[QuoteController::class,'update'])->name('quotes.update');Route::post('/quotes/{quote}/invoice',[InvoiceController::class,'store'])->name('invoices.store');Route::get('/settings',[SettingsController::class,'edit'])->name('settings.edit');Route::put('/settings',[SettingsController::class,'update'])->name('settings.update');});});
